import json, re
SP = "/private/tmp/claude-501/-Users-akima-workspace-claude-plugins/b9807760-a222-4bc1-91da-3136fdb14684/scratchpad/restructure"
O = json.load(open(SP + "/old_units.json", encoding="utf-8"))
USED = []
KIND = {"F": "Files", "A": "Approach", "T": "Test scenarios"}

def it(ref, *subs):
    """旧の項目を返す。subs は (旧, 新) の組。旧は必ず含まれていること"""
    u, k = ref.split(".")
    s = O[u]["fields"][KIND[k[0]]]["items"][int(k[1:])]
    for a, b in subs:
        assert a in s, (ref, a)
        s = s.replace(a, b)
    USED.append(ref)
    return s

def head(uid, field):
    return O[uid]["fields"][field]["head"]

def all_refs():
    out = []
    for u, d in O.items():
        for k, f in KIND.items():
            v = d["fields"].get(f)
            if v:
                out += [f"{u}.{k}{i}" for i in range(len(v["items"]))]
    return out

def render(units):
    out = []
    for n, u in enumerate(units, 1):
        out.append(f"### U{n}. {u['name']}")
        out.append("")
        out.append(f"- **Goal:** {u['goal']}")
        out.append(f"- **Requirements:** {u['req']}")
        out.append(f"- **Dependencies:** {u['deps']}")
        out.append("- **Files:**")
        for x in u["files"]:
            out.append(x if x.startswith("  - ") else "  - " + x)
        if u.get("approach"):
            out.append("- **Approach:**")
            for i, x in enumerate(u["approach"], 1):
                x = re.sub(r"^\s*\d+\.\s*", "", x)
                out.append(f"  {i}. {x}")
        if u.get("exec"):
            out.append(f"- **Execution note:** {u['exec']}")
        if u.get("patterns"):
            out.append(f"- **Patterns to follow:** {u['patterns']}")
        out.append("- **Test scenarios" + ("**" + u["tests_head"] if u.get("tests_head") else ":**"))
        for x in u["tests"]:
            out.append(x if x.startswith("  - ") else "  - " + x)
        out.append(f"- **Verification:** {u['verif']}")
        out.append("")
    return "\n".join(out)
EOF
echo ok

