python3 - <<'EOF'
import re
s = open("docs/plans/2026-10-06-2025-feat-issue-dispatch-plan.md", encoding="utf-8").read()
a = s.index("## Implementation Units"); b = s.index("## Verification Contract")
sec = s[a:b]
def expand(t):
    out = set()
    for m in re.finditer(r"U(\d+)(?:〜U(\d+))?", t):
        x = int(m.group(1)); y = int(m.group(2) or x)
        out |= set(range(x, y+1))
    return out
table = {}
for m in re.finditer(r"^\| U(\d+) \| [^|]+ \| [^|]+ \| (.*) \|$", sec, re.M):
    table[int(m.group(1))] = expand(m.group(2))
deps = {}
for m in re.finditer(r"^### U(\d+)\..*?^- \*\*Dependencies:\*\* (.*)$", sec, re.M | re.S):
    deps[int(m.group(1))] = expand(m.group(2))
for k in sorted(deps):
    t = table.get(k)
    flag = "" if t == deps[k] else "  <-- 違う"
    later = [d for d in deps[k] if d >= k]
    print(k, sorted(deps[k]), "table", sorted(t) if t is not None else None, flag, ("後の単位に依存: %s" % later) if later else "")
EOF

