import re,sys
s=open(sys.argv[1],encoding="utf-8").read()
def expand(t):
    out=set()
    for a,b in re.findall(r"U(\d+)〜U(\d+)",t):
        out|=set(range(int(a),int(b)+1))
    t2=re.sub(r"U\d+〜U\d+","",t)
    out|={int(x) for x in re.findall(r"U(\d+)",t2)}
    return out
table={}
for m in re.finditer(r"^\| U(\d+) \| [^|]+ \| .* \| ([^|]*) \|$",s,re.M):
    table[int(m.group(1))]=expand(m.group(2))
units={}
for m in re.finditer(r"^### U(\d+)\. .*?$(.*?)(?=^### U|\Z)",s,re.M|re.S):
    n=int(m.group(1)); body=m.group(2)
    d=re.search(r"^- \*\*Dependencies:\*\*(.*)$",body,re.M)
    units[n]=expand(d.group(1)) if d else None
print("units",sorted(units)); print("table",sorted(table))
for n in sorted(units):
    if units[n] is None: print(n,"no deps line"); continue
    if n in table and table[n]!=units[n]:
        print("U%d mismatch table-units:"%n, sorted(table[n]-units[n]), "units-table:", sorted(units[n]-table[n]))
    later=[x for x in units[n] if x>=n]
    if later: print("U%d depends on later/self"%n, later)
PYEOF
