cat > tmp/issue-dispatch-u1/latency.py <<'PYEOF'
# 書き込みの直後の読み取りの遅れを、書き込みの種類ごとに 10 回測る (U1 の項目 4)
import json, subprocess, time, sys
PID = "PVT_kwHNSeDOAZ7PAQ"; OWNER = "akm"; PNUM = "3"
ITEM = "PVTI_lAHNSeDOAZ7PAc4QcSM1"          # verify-a #3 の項目
REPO_A = "akm/issue-dispatch-verify-a"
ISSUE_N = 3; BLOCKER_N = 2
F_TEXT = "PVTF_lAHNSeDOAZ7PAc4ZkEvI"       # Agent session ID
F_STATUS = "PVTSSF_lAHNSeDOAZ7PAc4ZkEkP"; OPT = {"Ready": "70f9cc48", "In Progress": "47fc9ee4"}
Q = '''query($pid:ID!){ node(id:$pid){ ... on ProjectV2 { items(first:50){ nodes { id
  fieldValues(first:20){ nodes {
    ... on ProjectV2ItemFieldTextValue { text updatedAt field { ... on ProjectV2FieldCommon { name } } }
    ... on ProjectV2ItemFieldSingleSelectValue { name updatedAt field { ... on ProjectV2FieldCommon { name } } } } }
  content { ... on Issue { number repository { nameWithOwner }
    labels(first:10){ nodes { name } }
    blockedBy(first:10){ nodes { number } }
    comments(last:3){ nodes { body createdAt } } } } } } } }
  rateLimit { cost remaining } }'''
def gh(*args, inp=None):
    r = subprocess.run(["gh", *args], capture_output=True, text=True, input=inp)
    if r.returncode != 0: raise RuntimeError(r.stderr.strip()[:300])
    return r.stdout
def read():
    out = json.loads(gh("api", "graphql", "-f", f"query={Q}", "-F", f"pid={PID}"))
    item = next(n for n in out["data"]["node"]["items"]["nodes"] if n["id"] == ITEM)
    return item, out["data"]["rateLimit"]
def fv(item, name):
    for v in item["fieldValues"]["nodes"]:
        if v.get("field", {}).get("name") == name: return v.get("text") or v.get("name")
    return None
def wait_until(pred, limit=60.0):
    t0 = time.time(); n = 0
    while True:
        n += 1; item, rl = read(); el = time.time() - t0
        if pred(item): return el, n, rl["cost"]
        if el > limit: return None, n, rl["cost"]
        time.sleep(0.5)
results = {}
def run(kind, do_write, pred_factory):
    rows = []
    for i in range(10):
        time.sleep(1.0)
        arg = do_write(i)
        t_w = time.time(); el, n, cost = wait_until(pred_factory(i, arg))
        rows.append((el, n, cost)); print(kind, i, arg, el, n, cost, flush=True)
    results[kind] = rows
# 1. テキストのフィールド
run("field-text", lambda i: (gh("project", "item-edit", "--project-id", PID, "--id", ITEM, "--field-id", F_TEXT, "--text", f"u1-{i}"), f"u1-{i}")[1],
    lambda i, arg: (lambda item: fv(item, "Agent session ID") == arg))
# 2. Status
run("status", lambda i: (gh("project", "item-edit", "--project-id", PID, "--id", ITEM, "--field-id", F_STATUS, "--single-select-option-id", OPT["Ready" if i % 2 == 0 else "In Progress"]), "Ready" if i % 2 == 0 else "In Progress")[1],
    lambda i, arg: (lambda item: fv(item, "Status") == arg))
# 3. コメント
run("comment", lambda i: (gh("api", f"repos/{REPO_A}/issues/{ISSUE_N}/comments", "-f", f"body=u1 latency {i}"), f"u1 latency {i}")[1],
    lambda i, arg: (lambda item: any(c["body"] == arg for c in item["content"]["comments"]["nodes"])))
# 4. blockedBy (足す・外すを交互に)
def w_block(i):
    if i % 2 == 0: gh("issue", "edit", str(ISSUE_N), "-R", REPO_A, "--add-blocked-by", str(BLOCKER_N)); return "added"
    gh("issue", "edit", str(ISSUE_N), "-R", REPO_A, "--remove-blocked-by", str(BLOCKER_N)); return "removed"
run("blockedBy", w_block, lambda i, arg: (lambda item: (BLOCKER_N in [b["number"] for b in item["content"]["blockedBy"]["nodes"]]) == (arg == "added")))
# 5. ラベル (足す・外すを交互に)
try: gh("label", "create", "resource:verify", "-R", REPO_A, "--color", "0E8A16")
except RuntimeError: pass
def w_label(i):
    if i % 2 == 0: gh("issue", "edit", str(ISSUE_N), "-R", REPO_A, "--add-label", "resource:verify"); return "added"
    gh("issue", "edit", str(ISSUE_N), "-R", REPO_A, "--remove-label", "resource:verify"); return "removed"
run("label", w_label, lambda i, arg: (lambda item: ("resource:verify" in [l["name"] for l in item["content"]["labels"]["nodes"]]) == (arg == "added")))
json.dump(results, open("tmp/issue-dispatch-u1/latency.json", "w"), indent=1)
for k, rows in results.items():
    els = [r[0] for r in rows]; first = sum(1 for r in rows if r[1] == 1)
    print(f"{k}: 1 回目の読み取りで返った回数 {first}/10, 最大の遅れ {max(x for x in els if x is not None) if any(els) else None:.2f}s, 返らなかった回数 {sum(1 for x in els if x is None)}")
PYEOF
python3 tmp/issue-dispatch-u1/latency.py 2>&1 | tail -60

