set -e && R=akm/issue-dispatch-verify-a && RID=$(gh api repos/$R --jq .node_id) && HEAD=$(gh api repos/$R/git/ref/heads/main --jq .object.sha) && mk() { # branch file closes_issue draft
  gh api repos/$R/git/refs -f ref="refs/heads/$1" -f sha="$HEAD" >/dev/null
  gh api graphql -f query='mutation($b:CommittableBranch!,$h:GitObjectID!,$msg:String!,$path:String!,$c:Base64String!){ createCommitOnBranch(input:{branch:$b, expectedHeadOid:$h, message:{headline:$msg}, fileChanges:{additions:[{path:$path, contents:$c}]}}){ commit { oid } } }' -F "b={\"repositoryNameWithOwner\":\"$R\",\"branchName\":\"$1\"}" -F "h=$HEAD" -F "msg=U1: $2" -F "path=$2" -F "c=$(printf 'u1\n' | base64)" --jq .data.createCommitOnBranch.commit.oid >/dev/null
  gh api graphql -f query='mutation($r:ID!,$base:String!,$head:String!,$t:String!,$body:String!,$d:Boolean!){ createPullRequest(input:{repositoryId:$r, baseRefName:$base, headRefName:$head, title:$t, body:$body, draft:$d}){ pullRequest { number id } } }' -F r="$RID" -F base=main -F head="$1" -F "t=U1 $1" -F "body=Closes #$3" -F d=$4 --jq '.data.createPullRequest.pullRequest | "\(.number) \(.id)"'
}
read -r N1 ID1 <<<"$(mk u1-pr-1 u1-1.txt 1 true)"; echo "PR1 #$N1 (draft, Closes #1)"
sleep 2; gh api graphql -f query='mutation($id:ID!){ markPullRequestReadyForReview(input:{pullRequestId:$id}){ pullRequest { isDraft } } }' -F id="$ID1" --jq .data.markPullRequestReadyForReview.pullRequest.isDraft
sleep 2; gh pr merge $N1 -R $R --squash --delete-branch >/dev/null && echo "PR1 merged"
HEAD=$(gh api repos/$R/git/ref/heads/main --jq .object.sha)
read -r N2 ID2 <<<"$(mk u1-pr-2 u1-2.txt 2 false)"; echo "PR2 #$N2 (ready で作成, Closes #2)"
sleep 2; gh pr close $N2 -R $R >/dev/null && echo "PR2 closed without merge"
sleep 3; gh api graphql -f query='query { repository(owner:"akm", name:"issue-dispatch-verify-a") {
  i1: issue(number:1){ state closedByPullRequestsReferences(first:5, includeClosedPrs:true){ nodes { number state merged isDraft } } timelineItems(last:5, itemTypes:[CLOSED_EVENT]){ nodes { ... on ClosedEvent { createdAt closer { __typename ... on PullRequest { number } ... on Commit { oid } } } } } }
  i2: issue(number:2){ state closedByPullRequestsReferences(first:5, includeClosedPrs:true){ nodes { number state merged isDraft } } }
  p1: pullRequest(number:'$N1'){ isDraft merged createdAt timelineItems(first:20, itemTypes:[READY_FOR_REVIEW_EVENT, CONVERT_TO_DRAFT_EVENT, MERGED_EVENT, CLOSED_EVENT]){ nodes { __typename ... on ReadyForReviewEvent { createdAt } ... on MergedEvent { createdAt } ... on ClosedEvent { createdAt } ... on ConvertToDraftEvent { createdAt } } } }
  p2: pullRequest(number:'$N2'){ isDraft merged state timelineItems(first:20, itemTypes:[READY_FOR_REVIEW_EVENT, CONVERT_TO_DRAFT_EVENT, MERGED_EVENT, CLOSED_EVENT]){ nodes { __typename ... on ClosedEvent { createdAt } ... on ReadyForReviewEvent { createdAt } } } } } }' --jq '.data.repository'

